async function compileValidate (input, options = {}) {
  const originalEnv = Object.assign({}, process.env)
  try {
    return await compileValidateInEnvironment(input, options)
  } finally {
    for (const key of Object.keys(process.env)) {
      if (!Object.prototype.hasOwnProperty.call(originalEnv, key)) delete process.env[key]
    }
    Object.assign(process.env, originalEnv)
  }
}

async function compileValidateInEnvironment (input, options = {}) {
  const mpxPaths = (Array.isArray(input) ? input : [input]).map(p => path.resolve(p))
  for (const p of mpxPaths) {
    if (!fs.existsSync(p) || !fs.statSync(p).isFile()) {
      throw new InvalidInputError(`输入不是有效文件: ${p}`)
    }
  }
  const invalidConditions = mpxPaths.flatMap(p => {
    const result = validateConditionalCompile(p)
    return result.errors.map(error => `${result.file}:${error.line} ${error.message}`)
  })
  if (invalidConditions.length) {
    throw new InvalidInputError(
      `检测到无效的条件编译或 TODO 注释：\n- ${invalidConditions.join('\n- ')}`
    )
  }

  const {
    target = 'web',
    type = 'component',
    projectRoot: explicitRoot,
    ignoreSubComponents = true,
    cleanup = true
  } = options

  if (type !== 'page' && type !== 'component') {
    throw new InvalidInputError(`不支持的 type: ${type}，只接受 'page' 或 'component'`)
  }

  const projectRoot = explicitRoot
    ? path.resolve(explicitRoot)
    : resolveProjectRoot(mpxPaths[0])
  if (!projectRoot) {
    throw new MpxCliNotFoundError(
      `未找到安装了 @mpxjs/mpx-cli-service 的业务项目，无法执行真实编译校验。起点: ${mpxPaths[0]}`
    )
  }
  assertProjectDeps(projectRoot)

  const targets = Array.isArray(target) ? target : [target]
  if (targets.length === 1) {
    return compileOne(projectRoot, mpxPaths, targets[0], type, ignoreSubComponents, cleanup)
  }
  const out = {}
  for (const t of targets) {
    out[t] = await compileOne(projectRoot, mpxPaths, t, type, ignoreSubComponents, cleanup)
  }
  return out
}

